with RecentQuestions as (
    select p.Id, p.Title, p.OwnerUserId, p.CreationDate,
      row_number() over (partition by p.OwnerUserId order by p.CreationDate desc) as rq_rank
    from Posts p
    where p.PostTypeId = 1 -- questions
      and p.CreationDate >= now() - interval '90 day'
), TopUsers as (
    select u.Id, u.DisplayName, u.Reputation, u.CreationDate
    from Users u
    where u.Reputation >= 10000
      and u.CreationDate >= now() - interval '3 year'
), UserBadgeExplosion as (
    select bu.UserId, b.Name as BadgeName, 
      case when b.Class = 1 then 'Gold'
           when b.Class = 2 then 'Silver'
           when b.Class = 3 then 'Bronze'
           else 'Unknown'
      end as BadgeClass,
      dense_rank() over (partition by bu.UserId order by b.Class, b.Name) as rinsed_rank
    from Badges b 
    inner join Users u on b.UserId = u.Id
